  ('What is the human skeleton''s primary mineral component?', array['Iron','Calcium','Potassium','Zinc'], 1, 'medium'),
  ('Which gas makes up about 78% of Earth''s atmosphere?', array['Oxygen','Carbon dioxide','Nitrogen','Argon'], 2, 'medium'),
