  ('Which scientist discovered radioactivity along with her husband?', array['Rosalind Franklin','Marie Curie','Ada Lovelace','Lise Meitner'], 1, 'medium'),
  ('What is the term for the variety of life in a particular habitat?', array['Ecosystem','Biodiversity','Habitat','Population'], 1, 'medium'),
  ('Which is the largest ocean animal, also the largest animal ever known?', array['Great white shark','Blue whale','Giant squid','Orca'], 1, 'easy'),
